class Todo {
    private final int id;
    private final String judul;
    private boolean selesai;

    Todo(int id, String judul) {
        this.id = id;
        this.judul = judul;
    }

    int getId() {
        return id;
    }

    String getJudul() {
        return judul;
    }

    boolean isSelesai() {
        return selesai;
    }

    void selesaikan() {
        selesai = true;
    }

