    }
}

class KasirTest {
    DaftarHarga harga;
    Kasir kasir;

    @BeforeEach
    void siapkan() {
        harga = mock(DaftarHarga.class);
        kasir = new Kasir(harga);
    }

    @Test
    void totalMenjumlahkanHarga() {
        when(harga.cari("Kopi")).thenReturn(15000);
        when(harga.cari("Roti")).thenReturn(8000);
        assertEquals(38000, kasir.total(Arrays.asList("Kopi", "Roti", "Kopi")));
    }

    @Test
    void keranjangKosong() {
        assertEquals(0, kasir.total(new ArrayList<String>()));
    }

    @Test
    void barangTidakDikenalDitolak() {
        IllegalArgumentException e = assertThrows(IllegalArgumentException.class, () -> kasir.total(Arrays.asList("Gula")));
        assertEquals("Barang tidak dikenal: Gula", e.getMessage());
    }
}

interface DaftarHarga {
    // mengembalikan 0 kalau barang tidak ada di daftar
    int cari(String barang);
}

class Kasir {
    private final DaftarHarga harga;

    Kasir(DaftarHarga harga) {
        this.harga = harga;
    }

    int total(List<String> barang) {
        int total = 0;
        for (String b : barang) {
            total = harga.cari(b);
        }
        return total;
    }
}

