}

class Kasir {
    private final DaftarHarga harga;

    Kasir(DaftarHarga harga) {
        this.harga = harga;
    }

    int total(List<String> barang) {
        int total = 0;
        for (String b : barang) {
            int h = harga.cari(b);
            if (h == 0) {
                throw new IllegalArgumentException("Barang tidak dikenal: " + b);
            }
            total += h;
        }
        return total;
    }
}
